      <div class="alt-kpis"><span>Yield on cost <b>${Ut(T.quick.yieldOnCost)}</b></span><span>IRR <b>${Ut(T.quick.irr)}</b></span><span>NPV <b>${Xi(T.quick.npv)}</b></span><span>CAPEX <b>${Xi(T.quick.totalCapex,0)}</b></span>${ti("calculated",{formula:"Indicative model on predefined assumptions",sources:[`METHOD:USE-${T.use.id}`]})}</div>
