    <div class="table-wrap"><table class="tbl matrix"><thead><tr><th>Structure</th>${M.criteria.map($=>`<th class="r">${ie($.label)}<small>${$.effectiveWeight}%</small></th>`).join("")}<th class="r">Total</th></tr></thead><tbody>${M.applicable.map(($,D)=>`<tr class="${D===0?"chosen":""}"><td><b>${ie($.name.split(" (")[0])}</b><small class="muted">${ie($.termYears)}</small></td>${M.criteria.map(N=>`<td class="r heat" style="${gy($.scores[N.id])}">${$.scores[N.id]}</td>`).join("")}<td class="r total">${$.total.value}</td></tr>`).join("")}</tbody></table></div>
